import{d as c,C as t,o as u,c as m,j as a,a as s,E as n,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第五十八章","description":"从闷闷与察察、祸福转化到方廉直光，读有原则而不以原则伤物的治理。","frontmatter":{"title":"道德经第五十八章","description":"从闷闷与察察、祸福转化到方廉直光，读有原则而不以原则伤物的治理。","category":"guide","aliases":["道德经第五十八章","老子第五十八章","dao de jing chapter 58"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-58.md","filePath":"daoism/dao-de-jing/chapter-58.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-58.md"},_=c({...b,setup(p){const r=[{id:"two-governing-styles",label:"其政闷闷，其民淳淳",showLabel:!0,sentences:[["其政",{text:"闷闷",glossary:"menmen"},"，其民",{text:"淳淳",glossary:"chunchun"},"；其政",{text:"察察",glossary:"chacha"},"，其民",{text:"缺缺",glossary:"queque"},"。"]],note:["【白话】治理宽厚而不苛察，百姓便淳朴宽和；治理严密苛细，百姓反而生出巧伪与争竞。两句对照的是政与民如何相应。","【王弼注择要】淳淳下注「其民无所争竞，宽大淳淳」；察察下注「立刑名，明赏罚，以检奸伪」，缺缺则连「民奸争竞」解释。","【读法】闷闷不是官员昏睡不理事，察察也不等于所有审慎核查。这里分别批评把刑名赏罚、细密区分推成治理重心的倾向，字典为两词追加政治语境义。"]},{id:"fortune-and-misfortune",label:"祸兮福之所倚",showLabel:!0,sentences:[["祸兮福之所",{text:"倚",glossary:"yi"},"，福兮祸之所",{text:"伏",glossary:"fu"},"。"]],note:["【白话】祸患之中有福所依傍的条件，福庆之中也潜伏着祸患。眼前的祸福不能被当成永远固定、彼此隔绝的两面。","【读法】本句在所据录文未见单独逐句注，可接前文治理反效及后文正善转化读。倚是依傍，伏是潜藏，重在看见条件可能转移。","【读法】经句没有规定每次灾祸都会自动带来好处。面对实际伤害，仍要处理损失、提供帮助，不能拿祸福相倚替他人裁定苦难的价值。"]},{id:"the-limit-and-no-fixed-form",label:"孰知其极？其无正也",showLabel:!0,sentences:[["孰知其",{text:"极",glossary:"ji"},"？其无",{text:"正",glossary:"zhenglimit"},"也。"]],note:["【白话】按紧接祸福的一种句面读法：谁能知道它们的终极呢？它们并无固定不变的定准。本段另列王弼对善治之极的解释。","【王弼注择要】「言谁知善治之极乎？」注又说「唯无可正举，无可形名」，并以「闷闷然而天下大化，是其极也」收束。","【读法】王注把其极、无正接到善治无形无名，不能缩写成祸福永远无定准。本站保留也字，所据经文作其无正，不见也；正于此另列无固定可举形制义。"]},{id:"regularity-and-goodness-reversing",label:"正复为奇，善复为妖",showLabel:!0,sentences:[[{text:"正",glossary:"zheng"},"复为",{text:"奇",glossary:"qi"},"，善复为",{text:"妖",glossary:"yao"},"。"]],note:["【白话】正则又会转成奇变，标举的善也可能转为妖异之患。经文继续追问，为什么本来要纠正的手段，会生出相反的结果。","【王弼注择要】「以正治国，则便复以奇用兵矣。」善复为妖下注「立善以和万物，则便复有妖之患也」，与前章正奇相生的解释相接。","【读法】正、奇依此注连法度与奇变读；妖为反常之患。句子反省强立名目而求整齐的后果，并不取消对具体行为的善恶判断。"]},{id:"long-standing-confusion",label:"人之迷，其日固久",showLabel:!0,sentences:[["人之迷，其日固久。"]],note:["【白话】人的迷惑，延续的日子本来已经很长了。承上看，执着外在正善而失其道的偏差，不能只靠急切责求来改变。","【王弼注择要】「言人之迷惑失道固久矣。」注继而说「不可便正善治以责」，不把立正举善直接化为责人的工具。","【读法】固为本来；此句给后面的而不留下转折：帮助人复归，要辨明所失，也要改变令人更难复归的伤害方式。"]},{id:"principled-and-clean-without-cutting",label:"方而不割，廉而不刿",showLabel:!0,sentences:[["是以圣人",{text:"方",glossary:"fang"},"而不割，",{text:"廉",glossary:"lian"},"而不",{text:"刿",glossary:"gui"},"，"]],note:["【白话】所以圣人有方正的准则，却不以准则割伤人；有清廉的操守，却不以清廉刺伤物。所持的原则与运用原则的方式，要一起看。","【王弼注择要】方下注「以方导物」，又说「不以方割物」；廉下注「廉，清廉也；刿，伤也」，并说「不以清廉刿伤于物也」。","【读法】方仍可导物，廉仍可清民。两组而不反省的是以自居的尺度伤物，不等于为了和气就放弃原则或纵容侵害。"]},{id:"straight-and-bright-without-imposing",label:"直而不肆，光而不耀",showLabel:!0,sentences:[["直而不",{text:"肆",glossary:"si"},"，光而不",{text:"耀",glossary:"yao-light"},"。"]],note:["【白话】正直却不把自己的直强行施展于人，有光明却不以炫耀和穷察逼人。前段不割不刿，在这里延伸为不肆不耀。","【王弼注择要】直下注「不以直激沸于物也」；光下注「以光鉴其所以迷，不以光照求其隐匿也」。全段以「此皆崇本以息末，不攻而使复之也」总括。","【读法】王弼重在以明去迷，而不穷搜他人隐处。必要的查证仍需明确事实与边界，不把揭露他人、激化对立本身当作正直的证明。"]}],o=[{id:"menmen",term:"闷闷",sense:2},{id:"chunchun",term:"淳淳",sense:1},{id:"chacha",term:"察察",sense:2},{id:"queque",term:"缺缺",sense:1},{id:"yi",term:"倚",sense:1},{id:"fu",term:"伏",sense:1},{id:"ji",term:"极",sense:1},{id:"zhenglimit",term:"正",sense:3},{id:"zheng",term:"正",sense:2},{id:"qi",term:"奇",sense:1},{id:"yao",term:"妖",sense:1},{id:"fang",term:"方",sense:1},{id:"lian",term:"廉",sense:1},{id:"gui",term:"刿",sense:1},{id:"si",term:"肆",sense:1},{id:"yao-light",term:"耀",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十八章",tabindex:"-1"},[s("道德经第五十八章 "),a("a",{class:"header-anchor",href:"#道德经第五十八章","aria-label":'Permalink to "道德经第五十八章"'},"​")],-1)),n(i,{title:"有方、有廉、有光，为什么还要说不割、不刿、不耀",summary:"本章先对照两种治理与民情，再写祸福相倚、正善反转，最后以四组而不说明圣人的行事。王弼把无正连到善治无可正举、无可形名的状态，又以不攻而使复之贯通末段。",points:[{label:"先读",text:"闷闷与察察描述治理的作风，淳淳与缺缺写相应的民情，不按日常心情直译。"},{label:"再辨",text:"祸福相倚提出转化的复杂性；其无正在王弼注中另连善治的极处解释。"},{label:"后看",text:"方、廉、直、光仍被保留，变化在于不以它们割伤、逼迫或穷照他人。"}],hint:"闷闷按现有词头读 mèn mèn；淳淳读 chún chún，缺缺读 quē quē，刿读 guì，肆读 sì。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"其政闷闷，其民淳淳；其政察察，其民缺缺。",tone:"政与民相应",guide:"不只比较表面整齐，继续看治理是否增加争竞与巧伪。"},{text:"孰知其极？其无正也。",tone:"把两条解释分开",guide:"祸福无定准的句面读法，与王弼善治无形名之解，各自说明。"},{text:"是以圣人方而不割，廉而不刿，直而不肆，光而不耀。",tone:"四个而不",guide:"保有方廉直光，也检视它们是否变成伤物、迫人的手段。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=g("",15))])}}});export{y as __pageData,_ as default};
